(* [comment removed for export] *)
Lemma nafree_of_apart : forall A h lo n, VMcore A h -> 0 < lo -> 0 < n -> lo + n <= 2^64 ->
  (forall b sz, In (b, sz) (vm_maps h) -> lo + n <= bv_unsigned b \/ bv_unsigned b + bv_unsigned sz <= lo) ->
