    pm_areas : a_areas A = a_areas A0;
    pm_dom : forall x, dom A x -> dom A0 x;
    pm_vm : ms_vm s = ms_vm s0;
    pm_spare0 : spare A0 = 0;
    pm_init : a_ctx A KInit = 1;
    pm_amc : a_ctx A KAmc = 0;
    pm_fl : a_freelist A = [];
