    pm_aacA0 : a_ctx A0 KAac = 0;
    pm_xm : a_xmaps A = a_xmaps A0;
    pm_dom2 : forall x, dom A x <-> dom A0 x;
    pm_shift : a_ctx A KShift = a_ctx A0 KShift (* [comment removed for export] *) }.

